// Independent join of six or seven triple cells and the exact complementary large cells. Input: label quotas; allowed 3-multisets of triples; list of (pair of triple masks, admissible large cell). Lex DFS checks every three-triple submultiset; each large cell must survive every triple-pair domain. Repetitions allowed everywhere. Base-16 digits count incidences with no carry. Emit full mask tuples for further testing, not witnesses.
#include <algorithm>
#include <array>
#include <iostream>
#include <unordered_map>
#include <vector>
using namespace std;using U=unsigned long long;vector<int>T,W,Q;int index_[256];U code[256],goal,allow[56][56],all=~0ULL;bool dom[56][56][256];vector<int> path;unordered_map<U,vector<array<int,3>>>tails[2];long long visited[2],passed[2];
void dfs(int n,int lo,U live,U sum){if(path.size()==n){int k=n-6;visited[k]++;auto it=tails[k].find(goal-sum);if(it==tails[k].end())return;for(auto v:it->second){bool ok=true;for(int x:v)if(x)for(int i=0;i<n&&ok;i++)for(int j=0;j<i;j++)if(!dom[path[i]][path[j]][x]){ok=false;break;}if(!ok)continue;passed[k]++;for(int i:path)cout<<T[i]<<' ';for(int x:v)if(x)cout<<x<<' ';cout<<'\n';}return;}for(U bits=live&(all<<lo);bits;bits&=bits-1){int i=__builtin_ctzll(bits);U nx=live;for(int j:path)nx&=allow[i][j];path.push_back(i);dfs(n,i,nx,sum+code[T[i]]);path.pop_back();}}
int main(){for(int s=1;s<256;s++){for(int j=0;j<8;j++)if(s>>j&1)code[s]+=1ULL<<(4*j);int k=__builtin_popcount((unsigned)s);if(k==3){index_[s]=T.size();T.push_back(s);}if(k==4)W.push_back(s);if(k==5)Q.push_back(s);}for(int j=0;j<8;j++){int m;cin>>m;goal+=(U)m<<(4*j);}int nc;cin>>nc;for(int i=0;i<nc;i++){int x[3];for(int &s:x){cin>>s;s=index_[s];}for(int a=0;a<3;a++)for(int b=0;b<3;b++)if(a!=b)allow[x[a]][x[b]]|=1ULL<<x[3-a-b];}int nd;cin>>nd;for(int i=0;i<nd;i++){int a,b,s;cin>>a>>b>>s;dom[index_[a]][index_[b]][s]=dom[index_[b]][index_[a]][s]=true;}for(int x:W){for(int y:W)if(y>=x)for(int z:W)if(z>=y)tails[0][code[x]+code[y]+code[z]].push_back({x,y,z});for(int z:Q)tails[1][code[x]+code[z]].push_back({x,z,0});}for(int n:{6,7})dfs(n,0,(1ULL<<56)-1,0);cerr<<visited[0]<<' '<<visited[1]<<' '<<passed[0]<<' '<<passed[1]<<'\n';}
